// Fails the build when src/lib/icons.ts and the icon font subset disagree
// (the font is regenerated by `make icons`, which needs Python).
import { readFileSync } from 'node:fs';

const read = (p) => readFileSync(new URL(p, import.meta.url), 'utf8');
const block = read('../src/lib/icons.ts').match(/ICONS = \[([\s\S]*?)\] as const/);
if (!block) {
  console.error('check-icons: no ICONS list in src/lib/icons.ts');
  process.exit(1);
}
const listed = [...block[1].matchAll(/'([a-z0-9_]+)'/g)].map((m) => m[1]);
const inFont = JSON.parse(read('../src/assets/material-symbols-subset.json')).icons;
const add = listed.filter((n) => !inFont.includes(n));
const drop = inFont.filter((n) => !listed.includes(n));
if (add.length || drop.length) {
  console.error(`Icon font out of date${add.length ? ` · missing: ${add.join(', ')}` : ''}${drop.length ? ` · extra: ${drop.join(', ')}` : ''}.`);
  console.error('Run `make icons` (needs: pip install fonttools brotli).');
  process.exit(1);
}
